{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;

  var todos = [];
  var filter = 'all';

  // --- Model / localStorage ---

  /** @planks("localStorage has a key matching {string}") @planks("the stored value is a non-empty JSON array") @planks("the first stored todo has a title {string}") @planks("the first stored todo is not completed") @planks("the first stored todo has an id") @planks("the stored todo with title {string} is completed") @planks("the stored todos array is empty") @planks("the stored todo with title {string} exists") @planks("there is no stored todo with title {string}") @planks("the first todo item has the title {string}") @planks("the second todo item has the title {string}") @planks("the stored todos array is empty") */
  function loadTodos() {
    try {
      todos = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      todos = [];
    }
  }

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now() + Math.random().toString(36).substr(2, 9);
  }

  // --- Filter helpers ---

  /** @planks("the {string} filter link has the class {string}") @planks("the {string} filter link does not have the class {string}") @planks("navigating to the {string} filter shows {int} todo item(s)") */
  function getFilter() {
    var hash = window.location.hash || '';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function getFilteredTodos() {
    var f = getFilter();
    if (f === 'active') return todos.filter(function (t) { return !t.completed; });
    if (f === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function getActiveCount() {
    return todos.filter(function (t) { return !t.completed; }).length;
  }

  function getCompletedCount() {
    return todos.filter(function (t) { return t.completed; }).length;
  }

  // --- Render ---

  var todoApp = document.querySelector('.todoapp');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var toggleAllCheckbox = document.querySelector('.toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  /** @planks("the section with class {string} is not visible") @planks("the section with class {string} is visible") @planks("the footer element is not visible") @planks("the footer element is visible") @planks("the count shows {string}") @planks("the count text says {string}") @planks("the {string} filter link has the class {string}") @planks("the {string} filter link does not have the class {string}") @planks("I see {int} todo item") @planks("the {string} todo item is not visible") */
  function render() {
    var filtered = getFilteredTodos();
    var activeCount = getActiveCount();
    var completedCount = getCompletedCount();

    // Main and footer visibility
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = 'block';
      footer.style.display = 'block';
    }

    // Toggle-all state
    toggleAllCheckbox.checked = activeCount === 0 && todos.length > 0;

    // Generate list items
    var html = '';
    for (var i = 0; i < filtered.length; i++) {
      var todo = filtered[i];
      var liClass = '';
      if (todo.completed) liClass += ' completed';
      var checkedAttr = todo.completed ? 'checked' : '';
      html += '<li data-id="' + todo.id + '" class="' + liClass + '">';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox" ' + checkedAttr + '>';
      html += '<label>' + escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    }
    todoList.innerHTML = html;

    // Update count
    var word = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    // Clear completed visibility
    if (completedCount === 0) {
      clearCompleted.style.display = 'none';
    } else {
      clearCompleted.style.display = 'block';
    }

    // Filter link selected state
    var currentFilter = getFilter();
    for (var j = 0; j < filterLinks.length; j++) {
      var link = filterLinks[j];
      var href = link.getAttribute('href');
      if (href === '#/' && currentFilter === 'all') {
        link.className = 'selected';
      } else if (href === '#/active' && currentFilter === 'active') {
        link.className = 'selected';
      } else if (href === '#/completed' && currentFilter === 'completed') {
        link.className = 'selected';
      } else {
        link.className = '';
      }
    }

    // Save filter state
    localStorage.setItem(STORAGE_KEY + '-filter', currentFilter);
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // --- Actions ---

  /** @planks("a todo item with the title {string} appears in the list") @planks("the new-todo input is cleared") @planks("no new todo item is added") @planks("the count shows {string}") @planks("the count text says {string}") @planks("Todos are persisted to localStorage on creation") */
  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') return;
    todos.push({
      id: generateId(),
      title: trimmed,
      completed: false
    });
    saveTodos();
    render();
  }

  /** @planks("the {string} todo item has the class {string}") @planks("the {string} todo item does not have the class {string}") @planks("its toggle checkbox is checked") @planks("its toggle checkbox is not checked") @planks("the stored todo with title {string} is completed") */
  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos();
    render();
  }

  /** @planks("the {string} todo item is removed from the list") @planks("the stored todos array is empty") */
  function deleteTodo(id) {
    var newTodos = [];
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id !== id) {
        newTodos.push(todos[i]);
      }
    }
    todos = newTodos;
    saveTodos();
    render();
  }

  /** @planks("the {string} todo item is replaced by a todo item with the title {string}") @planks("the {string} todo item still has the title {string}") @planks("the stored todo with title {string} exists") @planks("there is no stored todo with title {string}") */
  function updateTodo(id, title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      deleteTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = trimmed;
        break;
      }
    }
    saveTodos();
    render();
  }

  /** @planks("all todo items have the class {string}") @planks("no todo items have the class {string}") @planks("the toggle-all checkbox is checked") @planks("the toggle-all checkbox is not checked") */
  function toggleAll() {
    var activeCount = getActiveCount();
    var allDone = activeCount === 0;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = !allDone;
    }
    saveTodos();
    render();
  }

  /** @planks("the {string} button is not visible") @planks("the {string} button is visible") @planks("the {string} todo item remains in the list") */
  function clearCompletedTodos() {
    var newTodos = [];
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) {
        newTodos.push(todos[i]);
      }
    }
    todos = newTodos;
    saveTodos();
    render();
  }

  // --- Event handlers ---

  function handleNewTodoKeydown(e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  }

  function handleTodoListClick(e) {
    var target = e.target;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;
    var id = li.getAttribute('data-id');

    if (target.className === 'toggle') {
      toggleTodo(id);
    } else if (target.className === 'destroy') {
      deleteTodo(id);
    }
  }

  function handleTodoListDblclick(e) {
    var target = e.target;
    if (target.tagName !== 'LABEL') return;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;

    // Put li in editing mode
    li.className = li.className + ' editing';
    var editInput = li.querySelector('.edit');
    editInput.value = editInput.value;
    editInput.focus();
    // Select text
    editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
  }

  function handleEditKeydown(e) {
    var target = e.target;
    if (target.className !== 'edit') return;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;
    var id = li.getAttribute('data-id');

    if (e.keyCode === ENTER_KEY) {
      updateTodo(id, target.value);
    } else if (e.keyCode === ESCAPE_KEY) {
      // Cancel, restore title
      for (var i = 0; i < todos.length; i++) {
        if (todos[i].id === id) {
          target.value = todos[i].title;
          break;
        }
      }
      li.className = li.className.replace(/\s*editing/g, '');
    }
  }

  function handleEditBlur(e) {
    var target = e.target;
    if (target.className !== 'edit') return;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;
    var id = li.getAttribute('data-id');

    // Save on blur if not already handled by keydown
    if (li.className.indexOf('editing') !== -1) {
      updateTodo(id, target.value);
    }
  }

  function handleToggleAllChange(e) {
    toggleAll();
  }

  function handleClearCompletedClick(e) {
    clearCompletedTodos();
  }

  // --- Filter persistence ---

  function restoreFilter() {
    var saved = localStorage.getItem(STORAGE_KEY + '-filter');
    if (saved === 'active' || saved === 'completed') {
      window.location.hash = '#/' + saved;
    } else {
      window.location.hash = '#/';
    }
  }

  // --- Hash change handler ---

  function handleHashChange() {
    render();
  }

  // --- Init ---

  function init() {
    loadTodos();
    restoreFilter();
    render();

    newTodoInput.addEventListener('keydown', handleNewTodoKeydown);
    todoList.addEventListener('click', handleTodoListClick);
    todoList.addEventListener('dblclick', handleTodoListDblclick);
    todoList.addEventListener('keydown', handleEditKeydown);
    todoList.addEventListener('blur', handleEditBlur, true);
    toggleAllCheckbox.addEventListener('change', handleToggleAllChange);
    clearCompleted.addEventListener('click', handleClearCompletedClick);
    window.addEventListener('hashchange', handleHashChange);
  }

  init();
})();

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  // `seed` is an optional object literal that is JSON.stringify'd into the new window's
  // localStorage at the STORAGE_KEY before app.js runs, so data-table steps can provision
  // state without a second load cycle.
  // `extraStorage` is an optional object of extra key-value pairs to write into localStorage.
  loadApp(seed, extraStorage) {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();

    // Seed localStorage before the app initialises.
    if (seed !== undefined) {
      this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(seed));
    }
    // Extra localStorage entries (e.g. persisted filter state).
    if (extraStorage !== undefined) {
      for (const [key, value] of Object.entries(extraStorage)) {
        this.window.localStorage.setItem(key, value);
      }
    }

    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

const { Given, When, Then, Before } = require('@cucumber/cucumber');
const assert = require('node:assert');

// -------------------------------------------------------------------------
// Background steps
// -------------------------------------------------------------------------

Given('the app is loaded', function () {
  // Already loaded by world.js Before hook
  assert.ok(this.document, 'app document should exist');
});

Given('there are no saved todos', function () {
  this.loadApp([]);
});

Given('the new-todo input is focused', function () {
  // The new-todo input should already be focused via autofocus
  // Focus it explicitly for the test
  const input = this.document.querySelector('.new-todo');
  input.focus();
});

// -------------------------------------------------------------------------
// Data table step - "the following todos exist:"
// -------------------------------------------------------------------------

Given('the following todos exist:', function (dataTable) {
  const rows = dataTable.hashes();
  const todos = rows.map(function (r) {
    return {
      id: Date.now() + Math.random().toString(36).substr(2, 9),
      title: r.title,
      completed: false
    };
  });
  this.loadApp(todos);
});

// -------------------------------------------------------------------------
// Completion steps
// -------------------------------------------------------------------------

Given('the {string} todo is completed', function (title) {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    if (stored[i].title === title) {
      stored[i].completed = true;
    }
  }
  this.loadApp(stored);
});

Given('all todos are completed', function () {
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  for (let i = 0; i < stored.length; i++) {
    stored[i].completed = true;
  }
  this.loadApp(stored);
});

// -------------------------------------------------------------------------
// Action steps (When)
// -------------------------------------------------------------------------

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  // Dispatch input event so app can listen if needed
  const evt = new this.window.Event('input', { bubbles: true });
  input.dispatchEvent(evt);
});

When('I press Enter', function () {
  // Check if an edit input exists and the app is in editing mode
  const inEdit = this.document.querySelector('.todo-list li.editing');
  const input = inEdit
    ? this.document.querySelector('.edit')
    : this.document.querySelector('.new-todo');
  const evt = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(evt);
});

When('I press Escape', function () {
  const editInput = this.document.querySelector('.edit');
  if (!editInput) return;
  const evt = new this.window.KeyboardEvent('keydown', {
    key: 'Escape',
    keyCode: 27,
    which: 27,
    bubbles: true
  });
  editInput.dispatchEvent(evt);
});

When('I click the toggle checkbox for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      const toggle = items[i].querySelector('.toggle');
      toggle.click();
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

When('I click the destroy button for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      const destroy = items[i].querySelector('.destroy');
      destroy.click();
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

When('I click the toggle-all checkbox', function () {
  const toggleAllCheckbox = this.document.querySelector('.toggle-all');
  // happy-dom click does not reliably fire change on checkboxes.
  // Dispatch change directly; the app handler does not read checkbox state.
  toggleAllCheckbox.checked = true;
  const evt = new this.window.Event('change', { bubbles: true });
  toggleAllCheckbox.dispatchEvent(evt);
});

When('I click the {string} button', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    btn.click();
  } else {
    assert.fail('Unknown button: ' + buttonText);
  }
});

When('I view the todo-count', function () {
  // Just a no-op assertion trigger, the count is always visible
});

When('I double-click the label for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      const evt = new this.window.MouseEvent('dblclick', {
        bubbles: true,
        detail: 2
      });
      label.dispatchEvent(evt);
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

When('I change the edit input value to {string}', function (text) {
  const editInput = this.document.querySelector('.edit');
  editInput.value = text;
  // Dispatch input event
  const evt = new this.window.Event('input', { bubbles: true });
  editInput.dispatchEvent(evt);
});

When('the edit input loses focus', function () {
  const editInput = this.document.querySelector('.edit');
  const evt = new this.window.Event('blur', { bubbles: true });
  editInput.dispatchEvent(evt);
});

When('I navigate to the {string} filter', function (filterName) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const hash = filterMap[filterName];
  assert.ok(hash, 'Unknown filter: ' + filterName);
  this.navigate(hash);
});

When('I reload the app', function () {
  // Preserve localStorage state across reload (new window has its own empty storage)
  const todos = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  const filter = this.localStorage.getItem('todos-vanillajs-filter');
  const extra = {};
  if (filter !== null) extra['todos-vanillajs-filter'] = filter;
  this.loadApp(todos, extra);
});

// -------------------------------------------------------------------------
// Assertion steps (Then)
// -------------------------------------------------------------------------

Then('a todo item with the title {string} appears in the list', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      found = true;
      break;
    }
  }
  assert.ok(found, 'Expected todo item "' + title + '" to appear in the list');
});

Then('the new-todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'new-todo input should be cleared');
});

Then('no new todo item is added', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  // The todo-list might be empty if no items
  // Just ensure count hasn't changed from what we expect
  const stored = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  assert.strictEqual(stored.length, 0, 'No todos should be stored');
});

Then('the {string} todo item has the class {string}', function (title, className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent === title) {
      assert.ok(items[i].classList.contains(className),
        'Expected "' + title + '" to have class "' + className + '"');
      return;
    }
  }
  assert.fail('Could not find todo item with title: ' + title);
});

Then('the {string} todo item does not have the class {string}', function (title, className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
